			capacity: 3,
			rate:     2,
			steps: []step{
				{n: 3, want: true},
				{advance: 1 * time.Second},
				{n: 2, want: true},
				{n: 1, want: false},
			},
		},
		{
			name:     "refill capped at capacity",
			capacity: 2,
			rate:     10,
			steps: []step{
				{n: 2, want: true},
				{advance: 10 * time.Second},
				{n: 2, want: true},
				{n: 1, want: false},
			},
		},
		{
			name:     "zero n always allowed",
			capacity: 1,
			rate:     1,
			steps: []step{
				{n: 0, want: true},
				{n: -1, want: true},
			},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			clk := newFakeClock()
			l, err := NewLimiter(tt.capacity, tt.rate, clk)
			if err != nil {
				t.Fatal(err)
			}
			for i, s := range tt.steps {
